//! End-to-end registration of a `did:webs` DID through the same
//! entry point every Trust Task transport uses.
//!
//! The fixture is an identifier created for `control.test`, which
//! designates itself there (regenerated by `webs_continuation`'s
//! `regenerate_control_fixture`). The reference publication cannot be
//! registered here: `affinidi-did-webs` 0.13 holds an identifier to the
//! domains its designated aliases name, and it names
//! `did-webs-service:7676`. Agreement with the ecosystem is asserted
//! against that publication where it is published
//! (`did-hosting-common`'s `method::webs` tests).

use super::test_helpers::*;
use super::*;

use crate::server::AppState;

const KERI: &[u8] =
    include_bytes!("../../../did-hosting-common/tests/fixtures/control-test/keri.cesr");
const AID: &str = "EALTc-6_o3G-p5jx7syeC46vpPAIjk1V58SNR3gyfT3A";
const DOMAIN: &str = "control.test";

fn keri() -> String {
    String::from_utf8(KERI.to_vec()).expect("CESR is UTF-8 text")
}

async fn record_for(state: &AppState, path: &str) -> DidRecord {
    state
        .dids_ks
        .get(did_key(path))
        .await
        .unwrap()
        .expect("record")
}

#[tokio::test]
async fn registers_a_webs_did_and_stores_its_key_event_log() {
    let (state, _dir) = test_state().await;
    let owner = "did:example:webs-owner";

    register_did_atomic(
        &owner_auth(owner),
        &state,
        AID,
        &keri(),
        false,
        Some(DOMAIN),
    )
    .await
    .expect("a verifying key event log registers");

    let record = record_for(&state, AID).await;
    assert_eq!(
        record.method, "webs",
        "tagged by the verifier that accepted it"
    );
    assert_eq!(record.owner, owner);
    assert_eq!(
        record.did_id.as_deref(),
        Some(format!("did:webs:{DOMAIN}:{AID}").as_str()),
        "the identifier is built from the slot, since a KEL carries no domain",
    );
    assert_eq!(
        record.domain, DOMAIN,
        "a did:webs record must carry its domain — its DID cannot be rebuilt without it",
    );

    // The CESR stream is stored verbatim under the same content
    // key every method's log lives at.
    let stored = state
        .dids_ks
        .get_raw(content_log_key(AID).as_str())
        .await
        .unwrap()
        .expect("stored log");
    assert_eq!(stored, KERI);
}

/// The binding that makes this hosting rather than file-serving:
/// a stream may only be published to the slot whose final path
/// segment is the AID that stream establishes.
#[tokio::test]
async fn refuses_a_log_published_to_another_aids_slot() {
    let (state, _dir) = test_state().await;
    let other = "EAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA";

    let err = register_did_atomic(
        &owner_auth("did:example:webs-owner"),
        &state,
        other,
        &keri(),
        false,
        Some(DOMAIN),
    )
    .await
    .expect_err("the key event log does not establish this slot's AID");
    assert!(
        matches!(err, AppError::Validation { .. }),
        "expected a validation refusal, got {err:?}",
    );
}

#[tokio::test]
async fn refuses_a_tampered_key_event_log() {
    let (state, _dir) = test_state().await;
    let mut tampered = KERI.to_vec();
    let pos = tampered
        .windows(3)
        .position(|w| w == b"\"s\"")
        .expect("inception has an `s` field");
    tampered[pos + 5] = b'9';
    let tampered = String::from_utf8(tampered).unwrap();

    let err = register_did_atomic(
        &owner_auth("did:example:webs-owner"),
        &state,
        AID,
        &tampered,
        false,
        Some(DOMAIN),
    )
    .await
    .expect_err("a tampered log must never be stored");
    assert!(matches!(err, AppError::Validation { .. }));

    assert!(
        state
            .dids_ks
            .get_raw(content_log_key(AID).as_str())
            .await
            .unwrap()
            .is_none(),
        "a refused publication must leave no content behind",
    );
}

/// A slot's method is fixed at registration. Swapping it would
/// change the identifier out from under everyone resolving it
/// while the record kept its owner and its agent names.
#[tokio::test]
async fn a_webs_slot_cannot_be_republished_as_webvh() {
    let (state, _dir) = test_state().await;
    let owner = "did:example:webs-owner";
    register_did_atomic(
        &owner_auth(owner),
        &state,
        AID,
        &keri(),
        false,
        Some(DOMAIN),
    )
    .await
    .expect("register");

    let webvh_log = concat!(
        r#"{"versionId":"1-zQmTest","versionTime":"2025-01-01T00:00:00Z","#,
        r#""state":{"id":"did:webvh:zQmTest:control.test:other"}}"#,
    );
    let err = publish_did(&owner_auth(owner), &state, AID, webvh_log, None)
        .await
        .expect_err("a did:webs slot must not accept a did:webvh log");
    assert!(
        err.to_string().contains("cannot be republished"),
        "expected a method-change refusal, got: {err}",
    );
}

/// A did:webs slot ends in a mixed-case AID, which the shared
/// path grammar rejects outright. If the method-aware validator
/// regressed, registration would fail before any verification
/// ran — so assert the shared rule really would have blocked it.
#[tokio::test]
async fn the_shared_path_grammar_would_have_rejected_this_slot() {
    assert!(
        did_hosting_common::server::mnemonic::validate_custom_path(AID).is_err(),
        "guard: if the shared grammar starts accepting AIDs, revisit the split",
    );

    let (state, _dir) = test_state().await;
    register_did_atomic(
        &owner_auth("did:example:webs-owner"),
        &state,
        AID,
        &keri(),
        false,
        Some(DOMAIN),
    )
    .await
    .expect("the method-aware validator must accept an AID slot");
}

async fn register_webs(state: &AppState, owner: &str) {
    register_did_atomic(&owner_auth(owner), state, AID, &keri(), false, Some(DOMAIN))
        .await
        .expect("register");
}

/// Reading a did:webs slot: the record and its stored stream, and no
/// did:webvh log metadata read out of a key event stream.
#[tokio::test]
async fn a_webs_slot_can_be_inspected() {
    let (state, _dir) = test_state().await;
    let owner = "did:example:webs-owner";
    register_webs(&state, owner).await;

    let (record, metadata) = get_did_info(&owner_auth(owner), &state, AID)
        .await
        .expect("info");
    assert_eq!(record.method, "webs");
    assert!(
        metadata.is_none(),
        "a key event stream has no webvh metadata"
    );

    let raw = get_raw_log(&owner_auth(owner), &state, AID)
        .await
        .expect("raw log");
    assert_eq!(raw.as_bytes(), KERI);

    let (domain, names) = list_agent_names(&owner_auth(owner), &state, AID, None)
        .await
        .expect("agent names");
    assert_eq!(domain, DOMAIN);
    assert!(names.is_empty());
}

/// Suspending and resuming a did:webs slot.
#[tokio::test]
async fn a_webs_slot_can_be_suspended_and_resumed() {
    let (state, _dir) = test_state().await;
    let owner = "did:example:webs-owner";
    register_webs(&state, owner).await;

    let record = set_did_disabled(&owner_auth(owner), &state, AID, true)
        .await
        .expect("suspend");
    assert!(record.disabled);
    assert!(record_for(&state, AID).await.disabled);

    let record = set_did_disabled(&owner_auth(owner), &state, AID, false)
        .await
        .expect("resume");
    assert!(!record.disabled);
}

/// Deleting a did:webs slot removes its record and its key event log.
#[tokio::test]
async fn a_webs_slot_can_be_deleted() {
    let (state, _dir) = test_state().await;
    let owner = "did:example:webs-owner";
    register_webs(&state, owner).await;

    let did_id = delete_did(&admin_auth("did:example:admin"), &state, AID, Some(DOMAIN))
        .await
        .expect("delete");
    assert_eq!(did_id, Some(format!("did:webs:{DOMAIN}:{AID}")));
    assert!(
        state
            .dids_ks
            .get::<DidRecord>(did_key(AID))
            .await
            .unwrap()
            .is_none()
    );
    assert!(
        state
            .dids_ks
            .get_raw(content_log_key(AID))
            .await
            .unwrap()
            .is_none()
    );
}

/// Rollback truncates a did:webvh log by line; it does not apply to a
/// key event stream, which is left as it was.
#[tokio::test]
async fn a_webs_slot_is_not_rolled_back() {
    let (state, _dir) = test_state().await;
    let owner = "did:example:webs-owner";
    register_webs(&state, owner).await;

    let err = rollback_did_to(&owner_auth(owner), &state, AID, Some(1))
        .await
        .expect_err("rollback refused");
    assert!(
        matches!(&err, AppError::Validation { message: m, .. } if m.contains("did:webs")),
        "got {err:?}"
    );
    let stored = state
        .dids_ks
        .get_raw(content_log_key(AID))
        .await
        .unwrap()
        .expect("stored log");
    assert_eq!(stored, KERI);
}

/// did-witness.json is a did:webvh artifact.
#[tokio::test]
async fn a_webs_slot_takes_no_witness_file() {
    let (state, _dir) = test_state().await;
    let owner = "did:example:webs-owner";
    register_webs(&state, owner).await;

    let witness = serde_json::json!({ "versionId": "1-x", "proof": {} });
    let err = upload_witness(
        &owner_auth(owner),
        &state,
        AID,
        witness.as_object().unwrap(),
    )
    .await
    .expect_err("refused");
    assert!(err.to_string().contains("did:webs"), "got {err}");
}

/// The looser grammar applies only to a slot recorded as did:webs: an
/// AID-shaped path with no record, or one holding another method, is
/// refused by the shared grammar as before.
#[tokio::test]
async fn the_aid_grammar_applies_only_to_a_webs_record() {
    let (state, _dir) = test_state().await;
    let owner = "did:example:webs-owner";

    let err = get_did_info(&owner_auth(owner), &state, AID)
        .await
        .expect_err("no record");
    assert!(matches!(err, AppError::Validation { .. }), "got {err:?}");

    register_webs(&state, owner).await;
    let mut record = record_for(&state, AID).await;
    record.method = "webvh".into();
    state.dids_ks.insert(did_key(AID), &record).await.unwrap();
    let err = delete_did(&owner_auth(owner), &state, AID, None)
        .await
        .expect_err("not a did:webs slot");
    assert!(matches!(err, AppError::Validation { .. }), "got {err:?}");
    assert!(
        state
            .dids_ks
            .get::<DidRecord>(did_key(AID))
            .await
            .unwrap()
            .is_some()
    );
}

#[tokio::test]
async fn refuses_a_webs_registration_without_a_domain() {
    let (state, _dir) = test_state().await;
    let err = register_did_atomic(
        &owner_auth("did:example:webs-owner"),
        &state,
        AID,
        &keri(),
        false,
        None,
    )
    .await
    .expect_err("a did:webs DID cannot be built without its domain");
    assert!(matches!(err, AppError::Validation { .. }));
}
